// Verus program
// Builds a Vec<i32> of the same length as the input Vec<T>, filled with 1s.

use vstd::prelude::*;

verus! {

fn ones_like<T>(a: &Vec<T>) -> (result: Vec<i32>)
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i < result.len() ==> result[i] == 1,
{
    let mut result: Vec<i32> = Vec::new();
    let n: usize = a.len();

    let mut i: usize = 0;

    while i < n
        invariant
            0 <= i <= n,
            result.len() == i,
            forall|j: int| 0 <= j < i ==> result[j] == 1,
        decreases (n - i)
    {
        result.push(1);
        i = i + 1;
    }

    result
}

} // verus!